## Execution Turn Schema

Each "turn" in the chat is one execution:

```ts
interface TurnData {
  execution: {
    id: string;
    status: ExecutionStatus;
    reason?: string;
    startedAt: Date;
    completedAt?: Date;
    costUsd?: number;
    tokenCount?: number;
  };
  prompt: string; // user's message for this turn
  steps: StepData[]; // agent's work steps
  toolExecutions: ToolData[]; // all tool calls in this turn
}

interface StepData {
  id: string;
  order: number;
  kind: string; // "agent"
  text?: string; // assistant's visible response
  status: StepStatus;
  createdAt: Date;
}

interface ToolData {
  id: string;
  order: number;
  stepId?: string;
  tool: string; // "searchWeb", "scrapeUrl", etc.
  status: "called" | "completed" | "failed";
  durationMs?: number;
  errorCode?: string;
  input?: Record<string, unknown>;
  output?: Record<string, unknown>;
}
```

---

