  researchTopic: { name: "researchTopic", label: "Researching", icon: "brain" },
  wireAction: { name: "wireAction", label: "Taking action", icon: "zap" },
  browserSessionCreate: {
    name: "browserSessionCreate",
    label: "Creating session",
    icon: "monitor",
  },
  browserSessionList: {
    name: "browserSessionList",
    label: "Listing sessions",
    icon: "list",
  },
  memoryStore: {
    name: "memoryStore",
    label: "Storing memory",
    icon: "database",
  },
