	listRuns: protectedProcedure
		.input(z.object({ limit: z.number().int().min(1).max(50).optional() }))
		.query(async ({ input, ctx }) => {
			const runs = await workflowService.listRuns(
				ctx.session.user.id,
				input.limit ?? 20,
			);
			return runs.map(({ workflow, execution }) => ({
