- [ ] **Step 1: Write the new `packages/auth/src/index.ts`** (replace entirely):

  ```ts
  import { createBrowserClient, createServerClient } from "@supabase/ssr";
  import { createClient } from "@supabase/supabase-js";
  import type { SupabaseClient } from "@supabase/supabase-js";
  import type { NextRequest } from "next/server";

  import { env } from "@aevryn/env/web";

  let browserClient: SupabaseClient | null = null;

  /** Client components: cookie-backed browser session, singleton. */
  export function createBrowserSupabase(): SupabaseClient {
      if (browserClient) return browserClient;
      browserClient = createBrowserClient(
          env.NEXT_PUBLIC_SUPABASE_URL,
          env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
      );
      return browserClient;
  }

  /**
   * Server (route handler / server action) client built from a NextRequest's
   * cookie header. Read-only setAll: the proxy chain (Task 4) is responsible
   * for rotating the access token, so handlers only ever read the cookie the
   * browser already sent.
   */
  export function createServerSupabase(req: NextRequest): SupabaseClient {
      const cookiePairs: { name: string; value: string }[] = [];
      const header = req.headers.get("cookie") ?? "";
      for (const part of header.split(";")) {
          const eq = part.indexOf("=");
          if (eq === -1) continue;
          cookiePairs.push({
              name: part.slice(0, eq).trim(),
              value: decodeURIComponent(part.slice(eq + 1).trim()),
          });
      }
      return createServerClient(
          env.NEXT_PUBLIC_SUPABASE_URL,
          env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
          {
              cookies: {
                  getAll: () => cookiePairs,
                  setAll: () => {
                      // Intentionally no-op: read-only adapter for handlers.
                  },
              },
          },
      );
  }

  export interface SessionUser {
      id: string;
      email: string;
      name: string;
      image: string | null;
  }

  /** Shape kept congruent with the previous ctx.session so tRPC routers don't change. */
  export type Session = { user: SessionUser } | null;

  export async function getSessionUser(req: NextRequest): Promise<Session> {
      const supabase = createServerSupabase(req);
      const { data, error } = await supabase.auth.getUser();
      if (error || !data.user) return null;
      const meta = data.user.user_metadata as Record<string, unknown>;
      return {
          user: {
              id: data.user.id,
              email: data.user.email ?? "",
              name:
                  (typeof meta.name === "string" && meta.name)
                  || data.user.email
                  || "User",
              image:
                  typeof meta.avatar_url === "string" ? meta.avatar_url : null,
          },
      };
  }
  ```

