- [ ] **Step 2: Rewrite `apps/web/src/proxy.ts`**

  ```ts
  import { createServerClient } from "@supabase/ssr";
  import { NextResponse, type NextRequest } from "next/server";
  import { env } from "@aevryn/env/web";
  import { evlogMiddleware } from "evlog/next";

  export async function proxy(request: NextRequest) {
      let response = NextResponse.next({ request });

      const supabase = createServerClient(
          env.NEXT_PUBLIC_SUPABASE_URL,
          env.NEXT_PUBLIC_SUPABASE_ANON_KEY,
          {
              cookies: {
                  getAll: () => request.cookies.getAll(),
                  setAll: (cookies) => {
                      cookies.forEach(({ name, value }) =>
                          request.cookies.set(name, value),
                      );
                      response = NextResponse.next({ request });
                      cookies.forEach(({ name, value, options }) =>
                          response.cookies.set(name, value, options),
                      );
                  },
              },
          },
      );

      const { data } = await supabase.auth.getUser();

      if (request.nextUrl.pathname.startsWith("/workspace") && !data.user) {
          const url = request.nextUrl.clone();
          url.pathname = "/login";
          url.searchParams.set("next", request.nextUrl.pathname);
          return NextResponse.redirect(url);
      }

      // evlog: preserve existing instrumentation. Adapt to the signature found
      // in Step 1 (handler may accept an optional request + event).
      const evlog = evlogMiddleware();
      const evlogResponse = await (evlog as unknown as (
          req: NextRequest,
      ) => Promise<Response | void | undefined>)(request);
      return evlogResponse ?? response;
  }

  export const config = {
      matcher: ["/api/:path*", "/workspace/:path*"],
  };
  ```

