  ```ts
  async getOrCreateChatExecution(workflowId, userId) {
      await this.requireOwnedWorkflow(workflowId, userId);
      const existing = await this.getExecutionForThread(workflowId); // latest chat/run-superseded row
      if (existing) return existing;
      return this.createExecution({
          workflowId,
          status: "running",
          reason: "chat_thread",
          prompt: "",
      });
  }

  async appendChatStep(workflowId, userId, input) {
      const execution = await this.getOrCreateChatExecution(workflowId, userId);
      const order = await this.nextStepOrder(execution.id);
      const step = await this.insertStep({
          executionId: execution.id,
          kind: input.role === "system" ? "system" : "chat",
          assistantText: input.text,
          order,
          idempotencyKey: input.refId ?? `${execution.id}-${order}`,
      });
      return step;
  }

  async appendToolEvent(workflowId, userId, toolName, input, output) {
      const execution = await this.getOrCreateChatExecution(workflowId, userId);
      const order = await this.nextStepOrder(execution.id);
      return this.insertToolExecution({
          workflowId,
          executionId: execution.id,
          order,
          tool: toolName,
          input,
          output,
          status: "completed",
      });
  }

  async saveDraftPlan(workflowId, userId, plan) {
      await this.requireOwnedWorkflow(workflowId, userId);
      const planId = await this.writePlan(workflowId, {
          title: plan.title,
          objective: plan.objective,
          summary: plan.summary,
          steps: plan.steps,
          kind: "plan",
      });
      return { planId };
  }

  async bindApprovedWorkflow(workflowId, userId) {
      await this.confirmWorkflow(workflowId, userId); // sets active + observation
  }

  async enqueueApprovedRun(workflowId, userId, prompt) {
      await this.requireOwnedWorkflow(workflowId, userId);
      const execution = await this.createExecution({
          workflowId,
          status: "running",
          reason: "run",
          prompt,
      });
      await this.insertObservation(workflowId, "plan_confirm", {
          executionId: execution.id,
      });
      return { workflowId, executionId: execution.id };
  }
