     user's answers). Calling it hands the pipeline to the durable worker.

  Never call finalizeAndInject without an explicit user approval. Do not invent
  the plan in a normal reply.`;

  export async function POST(req: NextRequest) {
      const session = await getSessionUser(req);
      if (!session) {
          return Response.json({ error: "Unauthorized" }, { status: 401 });
      }
      const userId = session.user.id;

      const body = (await req.json()) as { workflowId?: string; message?: string };
      const workflowId = body.workflowId;
      const message = (body.message ?? "").trim();
      if (!workflowId || !message) {
          return Response.json(
              { error: "workflowId and message are required" },
              { status: 400 },
          );
      }

      let history: Message[] = [];
      try {
          const turns = await workflowService.getMessages(workflowId, userId);
          history = convertToCoreMessages(
              turns
                  .filter((t) => t.role === "user" || t.role === "assistant")
                  .map((t) => ({
                      id: t.id,
                      role: t.role,
                      content: t.text,
                  })),
          );
      } catch {
          // First message in a fresh thread: no history yet.
      }

      const groq = createGroq({ apiKey: env.GROQ_API_KEY ?? "" });

      const result = streamText({
          model: groq(env.GROQ_MODEL),
          system: SYSTEM_PROMPT,
          messages: [...history, { role: "user", content: message }],
          tools: {
              askUserQuestion: tool({
                  description:
                      "Ask the user 2-5 counter-questions to clarify a plan. Render as a form.",
                  parameters: askUserQuestionSchema,
                  execute: async (args) => {
                      await workflowService.appendToolEvent(
                          workflowId,
                          userId,
                          "askUserQuestion",
                          args,
                          "pending_user_response",
                      );
                      return { kind: "question", ...args };
                  },
              }),
              showPlan: tool({
                  description:
                      "Present the finalized plan (title, summary, steps) for the run/approve decision.",
                  parameters: showPlanSchema,
                  execute: async (args) => {
                      await workflowService.saveDraftPlan(workflowId, userId, {
                          title: args.planTitle,
                          objective: args.planTitle,
                          summary: args.summary,
                          steps: args.steps,
                      });
                      return { kind: "plan", ...args };
                  },
              }),
              finalizeAndInject: tool({
                  description:
                      "Approved plan: bind the workflow to this thread and inject the durable run event.",
                  parameters: finalizeWorkflowSchema,
                  execute: async (args: z.infer<typeof finalizeWorkflowSchema>) => {
                      await workflowService.saveDraftPlan(workflowId, userId, args);
                      await workflowService.bindApprovedWorkflow(workflowId, userId);
                      const run = await workflowService.enqueueApprovedRun(
                          workflowId,
                          userId,
                          JSON.stringify(args),
                      );
                      await inngest.send({
                          name: executionRunEvent,
                          data: {
                              workflowId: run.workflowId,
                              executionId: run.executionId,
                              prompt: JSON.stringify(args),
                          },
                      });
                      await workflowService.appendToolEvent(
                          workflowId,
                          userId,
                          "finalizeAndInject",
                          args,
                          { accepted: true, executionId: run.executionId },
                      );
                      return {
                          kind: "injected",
                          executionId: run.executionId,
                          accepted: true,
                      };
                  },
              }),
          },
          maxSteps: 8,
          onFinish: async ({ text }) => {
              await workflowService.appendChatStep(workflowId, userId, {
                  role: "assistant",
                  text,
              });
          },
      });

      return result.toDataStreamResponse();
  }
  ```

  Notes: `getMessages` may not exist under that exact name — check the service
  in Step 0 of Task 2 and reuse the real conversation-reader (the
  `getThread` backing reader). `appendChatStep` for the assistant text runs in
  `onFinish` so the bubble persists even if the tab closes.

