		"waiting",
		"awaiting_approval",
		"paused",
	]),
	currentActivity: z.string().optional(),
	executionId: z.string().optional(),
	steps: z.array(
		z.object({
			order: z.number().int().min(0),
			text: z.string(),
		}),
	),
