export const createWebhookSchema = z.object({
	workflowId: z.string().min(1),
	executionId: z.string().min(1).optional(),
	instruction: z.string().min(1).max(2000),
	expiresInSeconds: z.number().int().min(60).max(2_592_000).optional(),
});

