+                isMulti ? (
+                  <CheckboxPrimitive.Root
+                    name={oid}
+                    className="sr-only"
+                    tabIndex={-1}
+                    aria-hidden
+                  />
+                ) : (
+                  <RadioPrimitive.Root
+                    value={oid}
+                    className="sr-only"
+                    tabIndex={-1}
+                    aria-hidden
+                  />
+                )
+              }
+            >
+              {question.layout === "stacked" ? (
+                <>
+                  <span className="inline-grid">
+                    <span
+                      className="col-start-1 row-start-1 invisible"
+                      style={{ fontVariationSettings: fontWeights.semibold }}
+                      aria-hidden="true"
+                    >
+                      {opt.title}
+                    </span>
+                    <span
+                      className="col-start-1 row-start-1 text-foreground transition-[color,font-variation-settings] duration-80"
+                      style={{
+                        fontVariationSettings: isSelected
+                          ? fontWeights.semibold
+                          : fontWeights.medium,
+                      }}
+                    >
+                      {opt.title}
+                    </span>
+                  </span>
+                  {opt.description && (
+                    <span
+                      className={cn(
+                        compact ? "text-[11px]" : "text-[12px]",
+                        "text-muted-foreground leading-snug"
+                      )}
+                    >
+                      {opt.description}
+                    </span>
+                  )}
+                </>
+              ) : (
+                <span>
+                  <span className="inline-grid">
+                    <span
+                      className="col-start-1 row-start-1 invisible"
+                      style={{ fontVariationSettings: fontWeights.semibold }}
+                      aria-hidden="true"
+                    >
+                      {opt.title}
+                    </span>
+                    <span
+                      className="col-start-1 row-start-1 text-foreground transition-[color,font-variation-settings] duration-80"
+                      style={{
+                        fontVariationSettings: isSelected
+                          ? fontWeights.semibold
+                          : fontWeights.medium,
+                      }}
+                    >
+                      {opt.title}
+                    </span>
+                  </span>
+                  {opt.description && (
+                    <>
+                      {" "}
+                      <span className="text-muted-foreground">
+                        {opt.description}
+                      </span>
+                    </>
+                  )}
+                </span>
+              )}
+            </Row>
+          );
+        })}
+
+        {allowOther && (
+          <Row
+            index={otherIndex}
+            registerItem={registerItem}
+            role={null}
+            isSelected={otherText.length > 0}
+            tabIndex={-1}
+            onClick={() => otherInputRef.current?.focus()}
+            shape={shape}
+            chipContent={otherIndex + 1}
+            chipFilled={otherText.length > 0}
+            isMulti={isMulti}
+            // Other body is a textarea that may grow past one line;
+            // only switch to top-aligned when it actually wraps, so
+            // the 1-line empty / single-line state stays visually
