+            showArrow={
+              !isMulti &&
+              (focusedIndex === otherIndex ||
+                activeIndex === otherIndex) &&
+              otherText.trim().length > 0
+            }
+            arrowIcon={
+              <ArrowRight
+                size={compact ? 12 : 14}
+                strokeWidth={2}
+                className={compact ? "h-3 w-3" : "h-3.5 w-3.5"}
+              />
+            }
+            onArrowClick={
+              !isMulti && otherText.trim().length > 0
+                ? handleOtherSubmit
+                : undefined
+            }
+          >
+            <span className="inline-grid w-full">
+              <textarea
+                ref={otherInputRef}
+                rows={1}
+                value={otherText}
