+                    value={otherText}
+                    onValueChange={handleOtherChange}
+                    render={
+                      <textarea
+                        ref={otherInputRef}
+                        rows={1}
+                        placeholder={
+                          question.freeTextPlaceholder ?? "Type your answer…"
