+                    <Field.Error
+                      key="ft-error"
+                      match
+                      render={
+                        <motion.p
+                          role="alert"
+                          initial={{ opacity: 0, y: -2 }}
+                          animate={{ opacity: 1, y: 0 }}
+                          transition={{
+                            ...spring.fast,
+                            opacity: { duration: 0.12 },
+                          }}
+                          className="min-w-0 px-2 sm:px-3 text-left text-[12px] leading-snug text-destructive"
+                        />
+                      }
+                    >
+                      {freeTextError}
+                    </Field.Error>
+                  )}
+                </div>
