+                                inside the button so it dims with the disabled
+                                state. ⌘↵ on macOS, ⌃↵ elsewhere. Desktop-only:
+                                mobile has no physical keyboard to trigger it. */}
+                            <span className="hidden sm:contents">
+                              <ShortcutChip shape={shape} tone="inverted">
+                                {isMac ? "⌘" : "⌃"}
+                                {"↵"}
+                              </ShortcutChip>
+                            </span>
+                          </span>
+                        </Button>
