+            <motion.span
+              className="inline-flex"
+              animate={{ rotate: group.open ? 90 : 0 }}
+              transition={spring.fast}
+            >
+              <ChevronRightIcon
+                size={sizeClasses.icon}
+                strokeWidth={1.5}
