+    return slotElement(
+      template,
+      "div",
+      {
+        ref: ref as Ref<HTMLElement>,
+        "data-sidebar": "group-label",
+        className: cn(
+          "flex h-8 shrink-0 items-center gap-2 px-2 text-muted-foreground/70 outline-none",
