+          className,
+        ),
+        ...props,
+      },
+      labelContent,
+    );
+  },
+);
+SidebarGroupLabel.displayName = "SidebarGroupLabel";
+
+export interface SidebarGroupActionProps extends HTMLAttributes<HTMLButtonElement> {
+  render?: ReactElement;
+  asChild?: boolean;
