import { monotonicFactory } from "ulid";

const factory = monotonicFactory();

export const ID_PREFIXES = {
	workflow: "wf_",
	execution: "exe_",
	step: "step_",
	tool: "tool_",
	observation: "obs_",
	recovery: "rec_",
	memory: "mem_",
	event: "evt_",
	agentState: "agent_state_",
	schedule: "sched_",
	notification: "ntf_",
	webhook: "whk_",
	approval: "ap_",
} as const;

export type IdPrefix = (typeof ID_PREFIXES)[keyof typeof ID_PREFIXES];

export function makeId(prefix: IdPrefix): string {
	return `${prefix}${factory()}`;
}

export function isValidId(prefix: IdPrefix, id: string): boolean {
	if (!id.startsWith(prefix)) return false;
	return /^[0-9A-HJKMNP-TV-Z]{26}$/.test(id.slice(prefix.length));
}

export const ids = {
	workflow: () => makeId(ID_PREFIXES.workflow),
	execution: () => makeId(ID_PREFIXES.execution),
	step: () => makeId(ID_PREFIXES.step),
	tool: () => makeId(ID_PREFIXES.tool),
	observation: () => makeId(ID_PREFIXES.observation),
	recovery: () => makeId(ID_PREFIXES.recovery),
	memory: () => makeId(ID_PREFIXES.memory),
	event: () => makeId(ID_PREFIXES.event),
	agentState: () => makeId(ID_PREFIXES.agentState),
	schedule: () => makeId(ID_PREFIXES.schedule),
	notification: () => makeId(ID_PREFIXES.notification),
	webhook: () => makeId(ID_PREFIXES.webhook),
	approval: () => makeId(ID_PREFIXES.approval),
} as const;

import { index, integer, pgTable, text, timestamp } from "drizzle-orm/pg-core";

import { WORKFLOW_STATUSES } from "../domain";
import { user } from "./auth";

export const workflow = pgTable(
	"workflow",
	{
		id: text("id").primaryKey(),
		userId: text("user_id")
			.notNull()
			.references(() => user.id, { onDelete: "cascade" }),
		objective: text("objective").notNull(),
		status: text("status", { enum: WORKFLOW_STATUSES })
			.notNull()
			.default("draft"),
		schemaVersion: integer("schema_version").notNull().default(1),
		createdAt: timestamp("created_at", { withTimezone: true })
			.defaultNow()
			.notNull(),
		updatedAt: timestamp("updated_at", { withTimezone: true })
			.defaultNow()
			.notNull()
			.$onUpdate(() => new Date()),
		archivedAt: timestamp("archived_at", { withTimezone: true }),
	},
	(table) => [
		index("workflow_user_status_idx").on(table.userId, table.status),
		index("workflow_user_created_idx").on(table.userId, table.createdAt),
	],
);

export type Workflow = typeof workflow.$inferSelect;
export type NewWorkflow = typeof workflow.$inferInsert;

