-- ============================================================
-- Aevryn: NEW schema (17 tables) — replaces legacy drizzle schema
-- Source of truth: final-docs/db/SCHEMA.md
-- ============================================================

-- #0 — Extensions
create extension if not exists pgcrypto with schema extensions;

-- ============================================================
-- #1 — Enums
-- ============================================================
create type public.role as enum ('owner', 'editor', 'viewer');
create type public.thread_role as enum ('editor', 'viewer');
create type public.plan_tier as enum ('free', 'pro');
create type public.group_kind as enum ('custom', 'system');
create type public.invite_kind as enum ('workspace', 'thread');
create type public.invite_status as enum ('pending', 'accepted', 'revoked', 'expired');
create type public.workflow_status as enum ('waiting', 'planning', 'running', 'awaiting_approval', 'idle', 'paused', 'failed', 'completed');
create type public.message_role as enum ('user', 'assistant', 'system', 'tool');
create type public.message_status as enum ('draft', 'queued', 'streaming', 'completed', 'failed', 'interrupted');
create type public.run_status as enum ('pending', 'running', 'sleeping', 'waiting', 'awaiting_approval', 'completed', 'failed', 'cancelled');
create type public.run_trigger as enum ('message', 'schedule', 'resume', 'approval', 'rerun');
create type public.activity_status as enum ('pending', 'active', 'complete', 'failed');
create type public.activity_type as enum ('tool', 'thinking', 'task', 'subtask', 'system');
create type public.approval_status as enum ('pending', 'approved', 'denied');
create type public.plan_status as enum ('draft', 'proposed', 'accepted', 'declined');
create type public.step_status as enum ('pending', 'active', 'completed', 'skipped');
create type public.api_provider as enum ('groq', 'anakin', 'mem0', 'image', 'speech', 'transcription', 'video');
create type public.notification_type as enum ('system', 'workflow', 'run', 'security', 'webhook');

-- ============================================================
-- #2 — Tables
-- ============================================================

-- 1. workspaces
create table public.workspaces (
	id text primary key,
	name text not null,
	created_by uuid not null references auth.users(id) on delete cascade,
	is_default boolean not null default false,
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now()
);
create unique index workspaces_created_by_name_idx on public.workspaces (created_by, name);

-- 2. groups (sidebar folder; INVITES is a LOCKED system group)
create table public.groups (
	id text primary key,
	workspace_id text not null references public.workspaces(id) on delete cascade,
	user_id uuid not null references auth.users(id) on delete cascade,
	name text not null,
	kind public.group_kind not null default 'custom',
	position int not null default 0,
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now()
);
create unique index groups_workspace_name_idx on public.groups (workspace_id, name);
create index groups_workspace_position_idx on public.groups (workspace_id, position);

-- 3. workspace_members (owner/editor/viewer; creator auto-inserted as owner by trigger)
create table public.workspace_members (
	id text primary key,
	workspace_id text not null references public.workspaces(id) on delete cascade,
	user_id uuid not null references auth.users(id) on delete cascade,
	role public.role not null default 'viewer',
	created_at timestamptz not null default now()
);
create unique index workspace_members_ws_user_idx on public.workspace_members (workspace_id, user_id);
create index workspace_members_user_idx on public.workspace_members (user_id);

-- 4. user_profiles
create table public.user_profiles (
	id text primary key,
	user_id uuid not null references auth.users(id) on delete cascade unique,
	onboarded boolean not null default false,
	pre_answers jsonb,
	plan public.plan_tier not null default 'free',
	prefer_own_keys_in_shared boolean not null default false,
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now()
);

-- 5. threads (chat container AND bound workflow; soft-archive via deleted_at)
create table public.threads (
	id text primary key,
	workspace_id text not null references public.workspaces(id) on delete cascade,
	group_id text references public.groups(id) on delete set null,
	user_id uuid not null references auth.users(id) on delete cascade,
	title text not null default '',
	deleted_at timestamptz,
	share_enabled boolean not null default false,
	bound_workflow_id text,
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now(),
	last_message_at timestamptz
);
create index threads_user_ws_lastmsg_idx on public.threads (user_id, workspace_id, last_message_at desc);
create index threads_group_idx on public.threads (group_id);
create index threads_title_lower_idx on public.threads (lower(title));

-- 6. workflows (bind target; bound to thread via threads.bound_workflow_id / workflow.thread_id)
create table public.workflows (
	id text primary key,
	thread_id text unique references public.threads(id) on delete set null,
	workspace_id text not null references public.workspaces(id) on delete cascade,
	user_id uuid not null references auth.users(id) on delete cascade,
	title text not null,
	description text,
	status public.workflow_status not null default 'idle',
	auto_approve boolean not null default false,
	schema_version int not null default 1,
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now()
);
create index workflows_user_status_idx on public.workflows (user_id, status);
create index workflows_thread_idx on public.workflows (thread_id);

-- threads.bound_workflow_id -> workflows (circular; add after both tables)
alter table public.threads
	add constraint threads_bound_workflow_id_fk
	foreign key (bound_workflow_id) references public.workflows(id) on delete set null;

-- 7. plans + plan_steps
create table public.plans (
	id text primary key,
	workflow_id text not null references public.workflows(id) on delete cascade unique,
	title text not null,
	objective text,
	summary text,
	status public.plan_status not null default 'proposed',
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now()
);

create table public.plan_steps (
	id text primary key,
	plan_id text not null references public.plans(id) on delete cascade,
	position int not null,
	title text not null,
	description text,
	status public.step_status not null default 'pending',
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now()
);
create unique index plan_steps_plan_position_idx on public.plan_steps (plan_id, position);

-- 8. chat_messages (single source of chat history; durable queue via status=queued)
create table public.chat_messages (
	id text primary key,
	thread_id text not null references public.threads(id) on delete cascade,
	user_id uuid not null references auth.users(id) on delete cascade,
	role public.message_role not null,
	content jsonb not null,
	run_id text references public.runs(id) on delete set null,
	status public.message_status not null default 'completed',
	queue_order int,
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now()
);
create index chat_messages_thread_created_idx on public.chat_messages (thread_id, created_at asc);
create index chat_messages_queued_idx on public.chat_messages (thread_id, status) where status = 'queued';

-- 9. runs
create table public.runs (
	id text primary key,
	thread_id text not null references public.threads(id) on delete cascade,
	workflow_id text references public.workflows(id) on delete set null,
	user_id uuid not null references auth.users(id) on delete cascade,
	trigger public.run_trigger not null default 'message',
	rerun_of text references public.runs(id) on delete set null,
	status public.run_status not null default 'pending',
	prompt_snapshot jsonb,
	cost_usd numeric(10, 6) not null default 0,
	token_count bigint not null default 0,
	started_at timestamptz,
	finished_at timestamptz,
	created_at timestamptz not null default now()
);
create index runs_thread_created_idx on public.runs (thread_id, created_at desc);
create index runs_workflow_status_idx on public.runs (workflow_id, status);

-- 10. run_activities (only AFTER runs exists)
create table public.run_activities (
	id text primary key,
	run_id text not null references public.runs(id) on delete cascade,
	parent_id text references public.run_activities(id) on delete set null,
	type public.activity_type not null default 'tool',
	status public.activity_status not null default 'pending',
	step_label text,
	title text,
	description text,
	detail jsonb,
	started_at timestamptz,
	completed_at timestamptz,
	created_at timestamptz not null default now()
);
create index run_activities_run_created_idx on public.run_activities (run_id, created_at asc);

-- 11. approval_requests
create table public.approval_requests (
	id text primary key,
	run_id text references public.runs(id) on delete cascade,
	workflow_id text references public.workflows(id) on delete cascade,
	thread_id text references public.threads(id) on delete cascade,
	user_id uuid not null references auth.users(id) on delete cascade,
	tool_name text not null,
	input jsonb,
	schema jsonb,
	status public.approval_status not null default 'pending',
	auto_approved boolean not null default false,
	resolved_at timestamptz,
	created_at timestamptz not null default now()
);
create index approval_requests_status_created_idx on public.approval_requests (status, created_at);
create index approval_requests_thread_idx on public.approval_requests (thread_id);

-- 12. invites (workspace + thread)
create table public.invites (
	id text primary key,
	kind public.invite_kind not null,
	workspace_id text not null references public.workspaces(id) on delete cascade,
	thread_id text references public.threads(id) on delete cascade,
	invited_by uuid not null references auth.users(id) on delete cascade,
	invitee_email text not null,
	invited_user_id uuid references auth.users(id) on delete set null,
	token_hash text not null unique,
	role public.thread_role not null default 'editor',
	status public.invite_status not null default 'pending',
	expires_at timestamptz,
	accepted_at timestamptz,
	created_at timestamptz not null default now()
);
create index invites_invitee_email_idx on public.invites (invitee_email);
create index invites_status_idx on public.invites (status);

-- 13. thread_shares (cross-workspace thread access in INVITES group)
create table public.thread_shares (
	id text primary key,
	thread_id text not null references public.threads(id) on delete cascade,
	user_id uuid not null references auth.users(id) on delete cascade,
	role public.thread_role not null default 'editor',
	invited_by uuid not null references auth.users(id) on delete cascade,
	invite_id text references public.invites(id) on delete cascade,
	created_at timestamptz not null default now()
);
create unique index thread_shares_thread_user_idx on public.thread_shares (thread_id, user_id);
create index thread_shares_user_idx on public.thread_shares (user_id);

-- 14. notifications
create table public.notifications (
	id text primary key,
	user_id uuid not null references auth.users(id) on delete cascade,
	workspace_id text references public.workspaces(id) on delete cascade,
	thread_id text references public.threads(id) on delete cascade,
	type public.notification_type not null default 'system',
	title text not null,
	body text,
	read_at timestamptz,
	created_at timestamptz not null default now()
);
create index notifications_user_state_idx on public.notifications (user_id, read_at, created_at desc);

-- 15. workspace_api_keys (never plaintext; encrypted / Supabase Vault)
create table public.workspace_api_keys (
	id text primary key,
	workspace_id text not null references public.workspaces(id) on delete cascade,
	created_by uuid not null references auth.users(id) on delete cascade,
	provider public.api_provider not null,
	key_encrypted bytea not null,
	model_name text,
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now()
);
create unique index workspace_api_keys_ws_provider_idx on public.workspace_api_keys (workspace_id, provider);

-- 16. files
create table public.files (
	id text primary key,
	user_id uuid not null references auth.users(id) on delete cascade,
	thread_id text references public.threads(id) on delete cascade,
	workspace_id text not null references public.workspaces(id) on delete cascade,
	bucket text not null default 'chat-attachments',
	path text not null,
	mime_type text,
	size_bytes bigint,
	compressed boolean not null default false,
	created_at timestamptz not null default now()
);
create index files_user_idx on public.files (user_id);
create index files_thread_idx on public.files (thread_id);

-- ============================================================
-- #3 — Drop legacy tables (old drizzle schema, now dead)
-- ============================================================
drop table if exists public.tool_execution cascade;
drop table if exists public.recovery_attempt cascade;
drop table if exists public.observation cascade;
drop table if exists public.agent_state cascade;
drop table if exists public.webhook_board cascade;
drop table if exists public.schedule cascade;
drop table if exists public.event cascade;
drop table if exists public.notification cascade;
drop table if exists public.approval cascade;
drop table if exists public.workflow_step cascade;
drop table if exists public.workflow_execution cascade;
drop table if exists public.workflow cascade;

-- ============================================================
-- #4 — RLS helpers (security definer, search_path pinned)
-- ============================================================
create or replace function public.is_workspace_member(p_workspace_id text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
	select exists (
		select 1 from public.workspace_members wm
		where wm.workspace_id = p_workspace_id
		  and wm.user_id = auth.uid()
	);
$$;

create or replace function public.is_workspace_owner(p_workspace_id text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
	select exists (
		select 1 from public.workspaces w
		where w.id = p_workspace_id
		  and w.created_by = auth.uid()
	);
$$;

create or replace function public.can_edit_workspace(p_workspace_id text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
	select exists (
		select 1 from public.workspace_members wm
		where wm.workspace_id = p_workspace_id
		  and wm.user_id = auth.uid()
		  and wm.role in ('owner', 'editor')
	);
$$;

create or replace function public.can_read_thread(p_thread_id text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
	select exists (
		select 1 from public.threads t
		where t.id = p_thread_id
		  and (
			t.user_id = auth.uid()
			or public.is_workspace_member(t.workspace_id)
			or exists (
				select 1 from public.thread_shares ts
				where ts.thread_id = t.id and ts.user_id = auth.uid()
			)
		  )
	);
$$;

-- ============================================================
-- #5 — RLS enable + policies (all authenticated)
-- ============================================================

-- workspaces
alter table public.workspaces enable row level security;
create policy workspaces_select on public.workspaces
	for select to authenticated
	using (created_by = auth.uid() or public.is_workspace_member(id));
create policy workspaces_owner_modify on public.workspaces
	for all to authenticated
	using (created_by = auth.uid())
	with check (created_by = auth.uid());

-- groups
alter table public.groups enable row level security;
create policy groups_select on public.groups
	for select to authenticated
	using (user_id = auth.uid() or public.is_workspace_member(workspace_id));
create policy groups_editor_modify on public.groups
	for all to authenticated
	using (user_id = auth.uid() or public.can_edit_workspace(workspace_id))
	with check (user_id = auth.uid() or public.can_edit_workspace(workspace_id));

-- workspace_members (owner manages; members select)
alter table public.workspace_members enable row level security;
create policy workspace_members_select on public.workspace_members
	for select to authenticated
	using (user_id = auth.uid() or public.is_workspace_member(workspace_id));
create policy workspace_members_owner_modify on public.workspace_members
	for all to authenticated
	using (public.is_workspace_owner(workspace_id))
	with check (public.is_workspace_owner(workspace_id));

-- user_profiles
alter table public.user_profiles enable row level security;
create policy user_profiles_own on public.user_profiles
	for all to authenticated
	using (user_id = auth.uid())
	with check (user_id = auth.uid());

-- threads
alter table public.threads enable row level security;
create policy threads_select on public.threads
	for select to authenticated
	using (
		user_id = auth.uid()
		or public.is_workspace_member(workspace_id)
		or exists (
			select 1 from public.thread_shares ts
			where ts.thread_id = id and ts.user_id = auth.uid()
		)
	);
create policy threads_editor_modify on public.threads
	for all to authenticated
	using (user_id = auth.uid() or public.can_edit_workspace(workspace_id))
	with check (user_id = auth.uid() or public.can_edit_workspace(workspace_id));

-- workflows
alter table public.workflows enable row level security;
create policy workflows_select on public.workflows
	for select to authenticated
	using (
		user_id = auth.uid()
		or public.is_workspace_member(workspace_id)
		or exists (
			select 1 from public.thread_shares ts
			where ts.thread_id = workflows.thread_id and ts.user_id = auth.uid()
		)
	);
create policy workflows_editor_modify on public.workflows
	for all to authenticated
	using (user_id = auth.uid() or public.can_edit_workspace(workspace_id))
	with check (user_id = auth.uid() or public.can_edit_workspace(workspace_id));

-- plans (read: anyone who can read the workflow; write: owner/editor)
alter table public.plans enable row level security;
create policy plans_select on public.plans
	for select to authenticated
	using (
		exists (
			select 1 from public.workflows w
			where w.id = plans.workflow_id
			  and (
				w.user_id = auth.uid()
				or public.is_workspace_member(w.workspace_id)
				or exists (
					select 1 from public.thread_shares ts
					where ts.thread_id = w.thread_id and ts.user_id = auth.uid()
				)
			  )
		)
	);
create policy plans_editor_modify on public.plans
	for all to authenticated
	using (
		exists (
			select 1 from public.workflows w
			where w.id = plans.workflow_id
			  and (w.user_id = auth.uid() or public.can_edit_workspace(w.workspace_id))
		)
	)
	with check (
		exists (
			select 1 from public.workflows w
			where w.id = plans.workflow_id
			  and (w.user_id = auth.uid() or public.can_edit_workspace(w.workspace_id))
		)
	);

-- plan_steps
alter table public.plan_steps enable row level security;
create policy plan_steps_select on public.plan_steps
	for select to authenticated
	using (
		exists (
			select 1 from public.plans p
			join public.workflows w on w.id = p.workflow_id
			where p.id = plan_steps.plan_id
			  and (
				w.user_id = auth.uid()
				or public.is_workspace_member(w.workspace_id)
				or exists (
					select 1 from public.thread_shares ts
					where ts.thread_id = w.thread_id and ts.user_id = auth.uid()
				)
			  )
		)
	);
create policy plan_steps_editor_modify on public.plan_steps
	for all to authenticated
	using (
		exists (
			select 1 from public.plans p
			join public.workflows w on w.id = p.workflow_id
			where p.id = plan_steps.plan_id
			  and (w.user_id = auth.uid() or public.can_edit_workspace(w.workspace_id))
		)
	)
	with check (
		exists (
			select 1 from public.plans p
			join public.workflows w on w.id = p.workflow_id
			where p.id = plan_steps.plan_id
			  and (w.user_id = auth.uid() or public.can_edit_workspace(w.workspace_id))
		)
	);

-- chat_messages (read/insert: anyone who can read the thread)
alter table public.chat_messages enable row level security;
create policy chat_messages_select on public.chat_messages
	for select to authenticated
	using (public.can_read_thread(thread_id));
create policy chat_messages_insert on public.chat_messages
	for insert to authenticated
	with check (public.can_read_thread(thread_id));
create policy chat_messages_modify on public.chat_messages
	for update to authenticated
	using (user_id = auth.uid())
	with check (user_id = auth.uid());

-- runs (read: thread readers; writes via service role)
alter table public.runs enable row level security;
create policy runs_select on public.runs
	for select to authenticated
	using (public.can_read_thread(thread_id));

-- run_activities (read: run readers; writes via service role)
alter table public.run_activities enable row level security;
create policy run_activities_select on public.run_activities
	for select to authenticated
	using (
		exists (
			select 1 from public.runs r
			where r.id = run_activities.run_id
			  and public.can_read_thread(r.thread_id)
		)
	);

-- approval_requests
alter table public.approval_requests enable row level security;
create policy approval_requests_select on public.approval_requests
	for select to authenticated
	using (public.can_read_thread(thread_id));
create policy approval_requests_update on public.approval_requests
	for update to authenticated
	using (public.can_read_thread(thread_id))
	with check (public.can_read_thread(thread_id));

-- invites (owner + invitee)
alter table public.invites enable row level security;
create policy invites_select on public.invites
	for select to authenticated
	using (invited_by = auth.uid() or invited_user_id = auth.uid());
create policy invites_owner_modify on public.invites
	for all to authenticated
	using (invited_by = auth.uid())
	with check (invited_by = auth.uid());

-- thread_shares (owner + shared user)
alter table public.thread_shares enable row level security;
create policy thread_shares_select on public.thread_shares
	for select to authenticated
	using (
		user_id = auth.uid()
		or exists (
			select 1 from public.threads t
			where t.id = thread_shares.thread_id and t.user_id = auth.uid()
		)
	);
create policy thread_shares_owner_modify on public.thread_shares
	for all to authenticated
	using (
		exists (
			select 1 from public.threads t
			where t.id = thread_shares.thread_id and t.user_id = auth.uid()
		)
	)
	with check (
		exists (
			select 1 from public.threads t
			where t.id = thread_shares.thread_id and t.user_id = auth.uid()
		)
	);

-- notifications (owner)
alter table public.notifications enable row level security;
create policy notifications_own on public.notifications
	for all to authenticated
	using (user_id = auth.uid())
	with check (user_id = auth.uid());

-- workspace_api_keys (owner; reads ONLY via get_workspace_key RPC)
alter table public.workspace_api_keys enable row level security;
create policy workspace_api_keys_owner on public.workspace_api_keys
	for all to authenticated
	using (created_by = auth.uid() or public.is_workspace_owner(workspace_id))
	with check (created_by = auth.uid() or public.is_workspace_owner(workspace_id));

-- files (owner)
alter table public.files enable row level security;
create policy files_own on public.files
	for all to authenticated
	using (user_id = auth.uid())
	with check (user_id = auth.uid());

-- ============================================================
-- #6 — get_workspace_key RPC (security definer; members only)
-- ============================================================
create or replace function public.get_workspace_key(p_workspace_id text, p_provider public.api_provider)
returns table (key_encrypted bytea, model_name text)
language sql
stable
security definer
set search_path = public
as $$
	select k.key_encrypted, k.model_name
	from public.workspace_api_keys k
	where k.workspace_id = p_workspace_id
	  and k.provider = p_provider
	  and (
		exists (
			select 1 from public.workspace_members wm
			where wm.workspace_id = p_workspace_id and wm.user_id = auth.uid()
		)
		or exists (
			select 1 from public.workspaces w
			where w.id = p_workspace_id and w.created_by = auth.uid()
		)
	  );
$$;

-- ============================================================
-- #7 — Triggers: limits + locked system groups
-- ============================================================

-- ≤5 active threads per group (soft-deleted excluded)
create or replace function public.enforce_thread_limit()
returns trigger
language plpgsql
security invoker
as $$
begin
	if exists (
		select 1
		from public.threads t
		where t.group_id = new.group_id
		  and t.deleted_at is null
		group by t.group_id
		having count(*) >= 5
	) then
		raise exception 'group thread limit reached (max 5 active threads per group)';
	end if;
	return new;
end;
$$;

create trigger threads_limit_trigger
	before insert on public.threads
	for each row execute function public.enforce_thread_limit();

-- ≤3 CUSTOM groups per workspace (system groups don't count)
create or replace function public.enforce_group_limit()
returns trigger
language plpgsql
security invoker
as $$
begin
	if new.kind = 'custom' and (
		select count(*) from public.groups g
		where g.workspace_id = new.workspace_id and g.kind = 'custom'
	) >= 3 then
		raise exception 'custom group limit reached (max 3 per workspace on free plan)';
	end if;
	return new;
end;
$$;

create trigger groups_limit_trigger
	before insert on public.groups
	for each row execute function public.enforce_group_limit();

-- System groups (PERSONAL/SITE/WORKFLOWS/INVITES) are LOCKED: no rename, no delete
create or replace function public.guard_system_group()
returns trigger
language plpgsql
security invoker
as $$
begin
	if old.kind = 'system' then
		raise exception 'system group is locked (cannot rename or delete)';
	end if;
	return new;
end;
$$;

create trigger groups_guard_system_trigger
	before update or delete on public.groups
	for each row execute function public.guard_system_group();

-- ============================================================
-- #8 — Storage bucket chat-attachments + policy
-- ============================================================
insert into storage.buckets (id, name, public)
values ('chat-attachments', 'chat-attachments', false)
on conflict (id) do nothing;

create or replace function public.is_own_storage_object()
returns boolean
language sql
stable
security definer
set search_path = storage
as $$
	select (storage.foldername(name))[1] = auth.uid()::text;
$$;

create policy chat_attachments_owner on storage.objects
	for all to authenticated
	using (bucket_id = 'chat-attachments' and public.is_own_storage_object())
	with check (bucket_id = 'chat-attachments' and public.is_own_storage_object());

-- ============================================================
-- #9 — Realtime publication (4 tables stream to the client)
-- ============================================================
alter publication supabase_realtime add table public.chat_messages;
alter publication supabase_realtime add table public.run_activities;
alter publication supabase_realtime add table public.approval_requests;
alter publication supabase_realtime add table public.notifications;

