+export const groupsRelations = relations(groups, ({ one, many }) => ({
+  workspace: one(workspaces, { fields: [groups.workspace_id], references: [workspaces.id] }),
+  threads: many(threads),
+}));
+
+export const workspaceMembersRelations = relations(workspaceMembers, ({ one }) => ({
+  workspace: one(workspaces, {
+    fields: [workspaceMembers.workspace_id],
+    references: [workspaces.id],
+  }),
+}));
+
+export const threadsRelations = relations(threads, ({ one, many }) => ({
+  workspace: one(workspaces, {
+    fields: [threads.workspace_id],
+    references: [workspaces.id],
+  }),
+  group: one(groups, { fields: [threads.group_id], references: [groups.id] }),
+  workflow: one(workflows, {
+    fields: [threads.bound_workflow_id],
+    references: [workflows.id],
+    relationName: "boundWorkflow",
+  }),
+  messages: many(chatMessages),
+  runs: many(runs),
+  approvals: many(approvalRequests),
+  shares: many(threadShares),
+  notifications: many(notifications),
+  files: many(files),
+}));
+
+export const workflowsRelations = relations(workflows, ({ one, many }) => ({
+  thread: one(threads, {
+    fields: [workflows.thread_id],
+    references: [threads.id],
+    relationName: "boundWorkflow",
+  }),
+  workspace: one(workspaces, {
+    fields: [workflows.workspace_id],
+    references: [workspaces.id],
+  }),
+  runs: many(runs),
+  plans: many(plans),
+  approvals: many(approvalRequests),
+}));
+
+export const plansRelations = relations(plans, ({ one, many }) => ({
+  workflow: one(workflows, { fields: [plans.workflow_id], references: [workflows.id] }),
+  steps: many(planSteps),
+}));
+
+export const planStepsRelations = relations(planSteps, ({ one }) => ({
+  plan: one(plans, { fields: [planSteps.plan_id], references: [plans.id] }),
