import { pgEnum } from "drizzle-orm/pg-core";

export const roleEnum = pgEnum("role", ["owner", "editor", "viewer"]);
export const threadRoleEnum = pgEnum("thread_role", ["editor", "viewer"]);
export const planTierEnum = pgEnum("plan", ["free", "pro"]);
export const groupKindEnum = pgEnum("group_kind", ["custom", "system"]);
export const inviteKindEnum = pgEnum("invite_kind", ["workspace", "thread"]);
export const inviteStatusEnum = pgEnum("invite_status", [
  "pending",
  "accepted",
  "revoked",
  "expired",
]);
export const workflowStatusEnum = pgEnum("workflow_status", [
  "waiting",
  "planning",
  "running",
  "awaiting_approval",
  "idle",
  "paused",
  "failed",
  "completed",
]);
export const messageRoleEnum = pgEnum("message_role", [
  "user",
  "assistant",
  "system",
  "tool",
]);
export const messageStatusEnum = pgEnum("message_status", [
  "draft",
  "queued",
  "streaming",
  "completed",
  "failed",
  "interrupted",
]);
export const runStatusEnum = pgEnum("run_status", [
  "pending",
  "running",
  "sleeping",
  "waiting",
  "awaiting_approval",
  "completed",
  "failed",
  "cancelled",
]);
export const runTriggerEnum = pgEnum("run_trigger", [
  "message",
  "schedule",
  "resume",
  "approval",
  "rerun",
]);
export const activityStatusEnum = pgEnum("activity_status", [
  "pending",
  "active",
  "complete",
  "failed",
]);
export const activityTypeEnum = pgEnum("activity_type", [
  "tool",
  "thinking",
  "task",
  "subtask",
  "system",
]);
export const approvalStatusEnum = pgEnum("approval_status", [
  "pending",
  "approved",
  "denied",
]);
export const planStatusEnum = pgEnum("plan_status", [
  "draft",
  "proposed",
  "accepted",
  "declined",
]);
export const stepStatusEnum = pgEnum("step_status", [
  "pending",
  "active",
  "completed",
  "skipped",
]);
export const apiProviderEnum = pgEnum("api_provider", [
  "groq",
  "anakin",
  "mem0",
  "image",
  "speech",
  "transcription",
  "video",
]);
export const notificationTypeEnum = pgEnum("notification_type", [
  "system",
  "workflow",
  "run",
  "security",
  "webhook",
]);

import { index, pgTable, boolean, text, timestamp, uuid } from "drizzle-orm/pg-core";

export const workspaces = pgTable(
  "workspaces",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    created_by: uuid("created_by").notNull(),
    is_default: boolean("is_default").notNull().default(false),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updated_at: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("workspaces_created_by_name").on(t.created_by, t.name)],
);

import {
  index,
  integer,
  pgTable,
  text,
  timestamp,
  uuid,
  unique,
} from "drizzle-orm/pg-core";
import { workspaces } from "./workspaces";
import { groupKindEnum } from "./enums";

export const groups = pgTable(
  "groups",
  {
    id: text("id").primaryKey(),
    workspace_id: text("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    user_id: uuid("user_id"),
    name: text("name").notNull(),
    kind: groupKindEnum("kind").notNull().default("custom"),
    position: integer("position").notNull().default(0),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updated_at: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("groups_workspace_id_name").on(t.workspace_id, t.name),
    index("groups_workspace_id_position").on(t.workspace_id, t.position),
  ],
);

import { pgTable, text, timestamp, uuid, unique } from "drizzle-orm/pg-core";
import { workspaces } from "./workspaces";
import { roleEnum } from "./enums";

export const workspaceMembers = pgTable(
  "workspace_members",
  {
    id: text("id").primaryKey(),
    workspace_id: text("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    user_id: uuid("user_id").notNull(),
    role: roleEnum("role").notNull().default("viewer"),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [unique("workspace_members_workspace_id_user_id").on(t.workspace_id, t.user_id)],
);

import { pgTable, boolean, jsonb, text, timestamp, uuid, unique } from "drizzle-orm/pg-core";
import { planTierEnum } from "./enums";

export const userProfiles = pgTable(
  "user_profiles",
  {
    id: text("id").primaryKey(),
    user_id: uuid("user_id").notNull(),
    onboarded: boolean("onboarded").notNull().default(false),
    pre_answers: jsonb("pre_answers").$type<Record<string, unknown>>(),
    plan: planTierEnum("plan").notNull().default("free"),
    prefer_own_keys_in_shared: boolean("prefer_own_keys_in_shared").notNull().default(false),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updated_at: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [unique("user_profiles_user_id").on(t.user_id)],
);

import {
  index,
  pgTable,
  boolean,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";
import { workspaces } from "./workspaces";
import { groups } from "./groups";

export const threads = pgTable(
  "threads",
  {
    id: text("id").primaryKey(),
    workspace_id: text("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    group_id: text("group_id").references(() => groups.id, { onDelete: "set null" }),
    user_id: uuid("user_id").notNull(),
    title: text("title").notNull().default(""),
    deleted_at: timestamp("deleted_at", { withTimezone: true }),
    share_enabled: boolean("share_enabled").notNull().default(false),
    bound_workflow_id: text("bound_workflow_id"),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updated_at: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
    last_message_at: timestamp("last_message_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("threads_user_workspace_last_message").on(t.user_id, t.workspace_id, t.last_message_at.desc()),
    index("threads_group_id").on(t.group_id),
    index("threads_title_lower").on(
      // eslint-disable-next-line drizzle/enforce-column-level-constraints
      (sql) => sql`lower(${t.title})`,
    ),
  ],
);

import { index, pgTable, boolean, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { workspaces } from "./workspaces";
import { groups } from "./groups";

export const threads = pgTable(
  "threads",
  {
    id: text("id").primaryKey(),
    workspace_id: text("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    group_id: text("group_id").references(() => groups.id, { onDelete: "set null" }),
    user_id: uuid("user_id").notNull(),
    title: text("title").notNull().default(""),
    deleted_at: timestamp("deleted_at", { withTimezone: true }),
    share_enabled: boolean("share_enabled").notNull().default(false),
    bound_workflow_id: text("bound_workflow_id"),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updated_at: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
    last_message_at: timestamp("last_message_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("threads_user_workspace_last_message").on(
      t.user_id,
      t.workspace_id,
      t.last_message_at.desc(),
    ),
    index("threads_group_id").on(t.group_id),
    index("threads_title_lower").on(sql`lower(${t.title})`),
  ],
);

import { index, pgTable, boolean, integer, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { threads } from "./threads";
import { workspaces } from "./workspaces";
import { workflowStatusEnum } from "./enums";

export const workflows = pgTable(
  "workflows",
  {
    id: text("id").primaryKey(),
    thread_id: text("thread_id").references(() => threads.id, { onDelete: "set null" }),
    workspace_id: text("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    user_id: uuid("user_id").notNull(),
    title: text("title").notNull(),
    description: text("description"),
    status: workflowStatusEnum("status").notNull().default("idle"),
    auto_approve: boolean("auto_approve").notNull().default(false),
    schema_version: integer("schema_version").notNull().default(1),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updated_at: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("workflows_user_status").on(t.user_id, t.status),
    index("workflows_thread_id").on(t.thread_id),
  ],
);

import { index, pgTable, integer, text, timestamp, unique } from "drizzle-orm/pg-core";
import { workflows } from "./workflows";
import { planStatusEnum, stepStatusEnum } from "./enums";

export const plans = pgTable(
  "plans",
  {
    id: text("id").primaryKey(),
    workflow_id: text("workflow_id")
      .notNull()
      .unique()
      .references(() => workflows.id, { onDelete: "cascade" }),
    title: text("title").notNull(),
    objective: text("objective"),
    summary: text("summary"),
    status: planStatusEnum("status").notNull().default("proposed"),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updated_at: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
);

export const planSteps = pgTable(
  "plan_steps",
  {
    id: text("id").primaryKey(),
    plan_id: text("plan_id")
      .notNull()
      .references(() => plans.id, { onDelete: "cascade" }),
    position: integer("position").notNull(),
    title: text("title").notNull(),
    description: text("description"),
    status: stepStatusEnum("status").notNull().default("pending"),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updated_at: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
