    workflow_id: text("workflow_id").references(() => workflows.id, { onDelete: "set null" }),
    user_id: uuid("user_id").notNull(),
    trigger: runTriggerEnum("trigger").notNull().default("message"),
    rerun_of: text("rerun_of"),
    status: runStatusEnum("status").notNull().default("pending"),
    prompt_snapshot: numeric("prompt_snapshot"),
    cost_usd: numeric("cost_usd", { precision: 10, scale: 6 }).notNull().default("0"),
