import { approvalRequests } from "./approval-requests";
import { invites } from "./invites";
import { threadShares } from "./thread-shares";
import { notifications } from "./notifications";
import { workspaceApiKeys } from "./workspace-api-keys";
import { files } from "./files";

export const workspacesRelations = relations(workspaces, ({ many }) => ({
  members: many(workspaceMembers),
  groups: many(groups),
  threads: many(threads),
  workflows: many(workflows),
  invites: many(invites),
  notifications: many(notifications),
  apiKeys: many(workspaceApiKeys),
  files: many(files),
}));

export const groupsRelations = relations(groups, ({ one, many }) => ({
  workspace: one(workspaces, { fields: [groups.workspace_id], references: [workspaces.id] }),
  threads: many(threads),
}));

export const workspaceMembersRelations = relations(workspaceMembers, ({ one }) => ({
  workspace: one(workspaces, {
    fields: [workspaceMembers.workspace_id],
    references: [workspaces.id],
  }),
}));

export const threadsRelations = relations(threads, ({ one, many }) => ({
  workspace: one(workspaces, {
    fields: [threads.workspace_id],
    references: [workspaces.id],
  }),
  group: one(groups, { fields: [threads.group_id], references: [groups.id] }),
  workflow: one(workflows, {
    fields: [threads.bound_workflow_id],
    references: [workflows.id],
    relationName: "boundWorkflow",
  }),
  messages: many(chatMessages),
  runs: many(runs),
  approvals: many(approvalRequests),
  shares: many(threadShares),
  notifications: many(notifications),
  files: many(files),
}));

export const workflowsRelations = relations(workflows, ({ one, many }) => ({
  thread: one(threads, {
    fields: [workflows.thread_id],
    references: [threads.id],
    relationName: "boundWorkflow",
  }),
  workspace: one(workspaces, {
    fields: [workflows.workspace_id],
    references: [workspaces.id],
  }),
  runs: many(runs),
  plans: many(plans),
  approvals: many(approvalRequests),
}));

export const plansRelations = relations(plans, ({ one, many }) => ({
  workflow: one(workflows, { fields: [plans.workflow_id], references: [workflows.id] }),
  steps: many(planSteps),
}));

export const planStepsRelations = relations(planSteps, ({ one }) => ({
  plan: one(plans, { fields: [planSteps.plan_id], references: [plans.id] }),
}));

export const chatMessagesRelations = relations(chatMessages, ({ one }) => ({
  thread: one(threads, {
    fields: [chatMessages.thread_id],
    references: [threads.id],
  }),
  run: one(runs, { fields: [chatMessages.run_id], references: [runs.id] }),
}));

export const runsRelations = relations(runs, ({ one, many }) => ({
  thread: one(threads, { fields: [runs.thread_id], references: [threads.id] }),
  workflow: one(workflows, {
    fields: [runs.workflow_id],
    references: [workflows.id],
  }),
  rerun: one(runs, { fields: [runs.rerun_of], references: [runs.id] }),
  activities: many(runActivities),
  messages: many(chatMessages),
  approvals: many(approvalRequests),
}));

export const runActivitiesRelations = relations(runActivities, ({ one }) => ({
  run: one(runs, { fields: [runActivities.run_id], references: [runs.id] }),
  parent: one(runActivities, {
    fields: [runActivities.parent_id],
    references: [runActivities.id],
  }),
}));

export const approvalRequestsRelations = relations(approvalRequests, ({ one }) => ({
  run: one(runs, { fields: [approvalRequests.run_id], references: [runs.id] }),
  workflow: one(workflows, {
    fields: [approvalRequests.workflow_id],
    references: [workflows.id],
  }),
  thread: one(threads, {
    fields: [approvalRequests.thread_id],
    references: [threads.id],
  }),
}));

export const invitesRelations = relations(invites, ({ one }) => ({
  workspace: one(workspaces, { fields: [invites.workspace_id], references: [workspaces.id] }),
  thread: one(threads, { fields: [invites.thread_id], references: [threads.id] }),
}));

export const threadSharesRelations = relations(threadShares, ({ one }) => ({
  thread: one(threads, { fields: [threadShares.thread_id], references: [threads.id] }),
  invite: one(invites, { fields: [threadShares.invite_id], references: [invites.id] }),
}));

export const notificationsRelations = relations(notifications, ({ one }) => ({
  workspace: one(workspaces, {
    fields: [notifications.workspace_id],
    references: [workspaces.id],
  }),
  thread: one(threads, {
    fields: [notifications.thread_id],
    references: [threads.id],
  }),
}));

export const workspaceApiKeysRelations = relations(workspaceApiKeys, ({ one }) => ({
  workspace: one(workspaces, {
    fields: [workspaceApiKeys.workspace_id],
    references: [workspaces.id],
  }),
}));

export const filesRelations = relations(files, ({ one }) => ({
  thread: one(threads, { fields: [files.thread_id], references: [threads.id] }),
  workspace: one(workspaces, {
    fields: [files.workspace_id],
    references: [workspaces.id],
  }),
}));

export const userProfilesRelations = relations(userProfiles, () => ({}));

