import { monotonicFactory } from "ulid";

const factory = monotonicFactory();

export const ID_PREFIXES = {
	workspace: "wp_",
	group: "grp_",
	workspaceMember: "wme_",
	profile: "prf_",
	thread: "thd_",
	workflow: "wf_",
	plan: "pln_",
	planStep: "pls_",
	message: "msg_",
	run: "run_",
	activity: "act_",
	approval: "apv_",
	invite: "inv_",
	threadShare: "tco_",
	notification: "not_",
	apiKey: "key_",
	file: "fil_",
} as const;

export type IdPrefix = (typeof ID_PREFIXES)[keyof typeof ID_PREFIXES];

export function makeId(prefix: IdPrefix): string {
	return `${prefix}${factory()}`;
}

export function isValidId(prefix: IdPrefix, id: string): boolean {
	if (!id.startsWith(prefix)) return false;
	return /^[0-9A-HJKMNP-TV-Z]{26}$/.test(id.slice(prefix.length));
}

export const ids = {
	workspace: () => makeId(ID_PREFIXES.workspace),
	group: () => makeId(ID_PREFIXES.group),
	workspaceMember: () => makeId(ID_PREFIXES.workspaceMember),
	profile: () => makeId(ID_PREFIXES.profile),
	thread: () => makeId(ID_PREFIXES.thread),
	workflow: () => makeId(ID_PREFIXES.workflow),
	plan: () => makeId(ID_PREFIXES.plan),
	planStep: () => makeId(ID_PREFIXES.planStep),
	message: () => makeId(ID_PREFIXES.message),
	run: () => makeId(ID_PREFIXES.run),
	activity: () => makeId(ID_PREFIXES.activity),
	approval: () => makeId(ID_PREFIXES.approval),
	invite: () => makeId(ID_PREFIXES.invite),
	threadShare: () => makeId(ID_PREFIXES.threadShare),
	notification: () => makeId(ID_PREFIXES.notification),
	apiKey: () => makeId(ID_PREFIXES.apiKey),
	file: () => makeId(ID_PREFIXES.file),
} as const;

export const ROLES = ["owner", "editor", "viewer"] as const;
export type Role = (typeof ROLES)[number];

export const THREAD_ROLES = ["editor", "viewer"] as const;
export type ThreadRole = (typeof THREAD_ROLES)[number];

export const PLANS = ["free", "pro"] as const;
export type PlanTier = (typeof PLANS)[number];

export const GROUP_KINDS = ["custom", "system"] as const;
export type GroupKind = (typeof GROUP_KINDS)[number];

export const INVITE_KINDS = ["workspace", "thread"] as const;
export type InviteKind = (typeof INVITE_KINDS)[number];

export const INVITE_STATUSES = ["pending", "accepted", "revoked", "expired"] as const;
export type InviteStatus = (typeof INVITE_STATUSES)[number];

export const WORKFLOW_STATUSES = [
	"waiting",
	"planning",
	"running",
	"awaiting_approval",
	"idle",
	"paused",
	"failed",
	"completed",
] as const;
export type WorkflowStatus = (typeof WORKFLOW_STATUSES)[number];

export const MESSAGE_ROLES = ["user", "assistant", "system", "tool"] as const;
export type MessageRole = (typeof MESSAGE_ROLES)[number];

