import { getTableConfig, getTableName } from 'drizzle-orm/pg-core';
const idx = await import('./src/schema/index.ts');
for (const [name, val] of Object.entries(idx)) {
  if (!name.endsWith('Relations') && val && val[Symbol.for('drizzle:Name')]) {
    try {
      const cfg = getTableConfig(val);
      for (const fk of cfg.foreignKeys) {
        const ref = fk.reference();
        getTableName(ref.foreignTable);
        ref.foreignColumns.forEach(c => { if (!c) throw new Error('undef col'); });
      }
      console.log('ok', name);
    } catch (e) {
      console.log('FAIL', name, '->', e.message);
    }
  }
}
"

