import { bigint, index, jsonb, numeric, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { threads } from "./threads";
import { workflows } from "./workflows";
import { runStatusEnum, runTriggerEnum } from "./enums";

export const runs = pgTable(
  "runs",
  {
    id: text("id").primaryKey(),
    thread_id: text("thread_id")
      .notNull()
      .references(() => threads.id, { onDelete: "cascade" }),
    workflow_id: text("workflow_id").references(() => workflows.id, { onDelete: "set null" }),
    user_id: uuid("user_id").notNull(),
    trigger: runTriggerEnum("trigger").notNull().default("message"),
    rerun_of: text("rerun_of"),
    status: runStatusEnum("status").notNull().default("pending"),
    prompt_snapshot: jsonb("prompt_snapshot").$type<Record<string, unknown>>(),
    cost_usd: numeric("cost_usd", { precision: 10, scale: 6 }).notNull().default("0"),
    token_count: bigint("token_count", { mode: "number" }).notNull().default(0),
    started_at: timestamp("started_at", { withTimezone: true }),
    finished_at: timestamp("finished_at", { withTimezone: true }),
    created_at: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("runs_thread_created").on(t.thread_id, t.created_at.desc()),
    index("runs_workflow_status").on(t.workflow_id, t.status),
  ],
);

