-- runs (read: thread readers; writes via service role)
alter table public.runs enable row level security;
create policy runs_select on public.runs
	for select to authenticated
	using (public.can_read_thread(thread_id));

-- run_activities (read: run readers; writes via service role)
alter table public.run_activities enable row level security;
create policy run_activities_select on public.run_activities
	for select to authenticated
	using (
		exists (
			select 1 from public.runs r
			where r.id = run_activities.run_id
			  and public.can_read_thread(r.thread_id)
		)
	);

-- approval_requests
alter table public.approval_requests enable row level security;
create policy approval_requests_select on public.approval_requests
	for select to authenticated
	using (public.can_read_thread(thread_id));
create policy approval_requests_update on public.approval_requests
	for update to authenticated
	using (public.can_read_thread(thread_id))
	with check (public.can_read_thread(thread_id));

-- invites (owner + invitee)
alter table public.invites enable row level security;
create policy invites_select on public.invites
	for select to authenticated
	using (invited_by = auth.uid() or invited_user_id = auth.uid());
create policy invites_owner_modify on public.invites
	for all to authenticated
	using (invited_by = auth.uid())
	with check (invited_by = auth.uid());

-- thread_shares (owner + shared user)
alter table public.thread_shares enable row level security;
create policy thread_shares_select on public.thread_shares
	for select to authenticated
	using (
		user_id = auth.uid()
		or exists (
			select 1 from public.threads t
			where t.id = thread_shares.thread_id and t.user_id = auth.uid()
		)
	);
create policy thread_shares_owner_modify on public.thread_shares
	for all to authenticated
	using (
		exists (
			select 1 from public.threads t
			where t.id = thread_shares.thread_id and t.user_id = auth.uid()
		)
	)
	with check (
		exists (
			select 1 from public.threads t
			where t.id = thread_shares.thread_id and t.user_id = auth.uid()
		)
	);

-- notifications (owner)
alter table public.notifications enable row level security;
create policy notifications_own on public.notifications
	for all to authenticated
	using (user_id = auth.uid())
	with check (user_id = auth.uid());

-- workspace_api_keys (owner; reads ONLY via get_workspace_key RPC)
alter table public.workspace_api_keys enable row level security;
create policy workspace_api_keys_owner on public.workspace_api_keys
	for all to authenticated
	using (created_by = auth.uid() or public.is_workspace_owner(workspace_id))
	with check (created_by = auth.uid() or public.is_workspace_owner(workspace_id));

-- files (owner)
alter table public.files enable row level security;
create policy files_own on public.files
	for all to authenticated
	using (user_id = auth.uid())
	with check (user_id = auth.uid());

-- ============================================================
-- #6 — get_workspace_key RPC (security definer; members only)
-- ============================================================
create or replace function public.get_workspace_key(p_workspace_id text, p_provider public.api_provider)
returns table (key_encrypted bytea, model_name text)
language sql
stable
security definer
set search_path = public
as $$
	select k.key_encrypted, k.model_name
	from public.workspace_api_keys k
	where k.workspace_id = p_workspace_id
	  and k.provider = p_provider
	  and (
		exists (
			select 1 from public.workspace_members wm
			where wm.workspace_id = p_workspace_id and wm.user_id = auth.uid()
		)
		or exists (
			select 1 from public.workspaces w
			where w.id = p_workspace_id and w.created_by = auth.uid()
		)
	  );
$$;

-- ============================================================
-- #7 — Triggers: limits + locked system groups
-- ============================================================

-- ≤5 active threads per group (soft-deleted excluded)
create or replace function public.enforce_thread_limit()
returns trigger
language plpgsql
security invoker
as $$
begin
	if exists (
		select 1
		from public.threads t
		where t.group_id = new.group_id
		  and t.deleted_at is null
		group by t.group_id
		having count(*) >= 5
	) then
		raise exception 'group thread limit reached (max 5 active threads per group)';
	end if;
	return new;
end;
$$;

create trigger threads_limit_trigger
	before insert on public.threads
	for each row execute function public.enforce_thread_limit();

-- ≤3 CUSTOM groups per workspace (system groups don't count)
create or replace function public.enforce_group_limit()
returns trigger
language plpgsql
security invoker
as $$
begin
	if new.kind = 'custom' and (
		select count(*) from public.groups g
		where g.workspace_id = new.workspace_id and g.kind = 'custom'
	) >= 3 then
		raise exception 'custom group limit reached (max 3 per workspace on free plan)';
	end if;
	return new;
end;
$$;

create trigger groups_limit_trigger
	before insert on public.groups
	for each row execute function public.enforce_group_limit();

-- System groups (PERSONAL/SITE/WORKFLOWS/INVITES) are LOCKED: no rename, no delete
create or replace function public.guard_system_group()
returns trigger
language plpgsql
security invoker
as $$
begin
	if old.kind = 'system' then
		raise exception 'system group is locked (cannot rename or delete)';
	end if;
	return new;
end;
$$;

create trigger groups_guard_system_trigger
	before update or delete on public.groups
	for each row execute function public.guard_system_group();

-- ============================================================
-- #8 — Storage bucket chat-attachments + policy
-- ============================================================
insert into storage.buckets (id, name, public)
values ('chat-attachments', 'chat-attachments', false)
on conflict (id) do nothing;

create or replace function public.is_own_storage_object()
returns boolean
language sql
stable
security definer
set search_path = storage
as $$
	select (storage.foldername(name))[1] = auth.uid()::text;
$$;

create policy chat_attachments_owner on storage.objects
	for all to authenticated
	using (bucket_id = 'chat-attachments' and public.is_own_storage_object())
	with check (bucket_id = 'chat-attachments' and public.is_own_storage_object());

-- ============================================================
-- #9 — Realtime publication (4 tables stream to the client)
-- ============================================================
alter publication supabase_realtime add table public.chat_messages;
alter publication supabase_realtime add table public.run_activities;
alter publication supabase_realtime add table public.approval_requests;

