import { customType } from "drizzle-orm/pg-core";

export const bytea = customType<{ data: Uint8Array; driverData: Buffer }>({
	dataType() {
		return "bytea";
	},
	toDriver(value) {
		return Buffer.from(value as Uint8Array);
	},
	fromDriver(value) {
		return new Uint8Array(value);
	},
});

